 as x(id text,friend_id text,category_code text,old_key text,asset jsonb);
do $guard$ begin
 if (select count(*) from gift_art260_updates)<>32 or
 (select count(*) from catalog_items c join gift_art260_updates u on c.stable_id=u.id
  where c.metadata->>'friendId'=u.friend_id and c.metadata->>'giftCategoryCode'=u.category_code
   and 'adventure_v2_gift'=any(c.tags) and c.asset->>'key' in(u.old_key,u.asset->>'key'))<>32
 then raise exception 'Collectible art identity/version mismatch; no data changed'; end if;
end $guard$;
update public.catalog_items c set asset=u.asset,updated_at=now()
from gift_art260_updates u where c.stable_id=u.id and c.asset is distinct from u.asset;
-- Presentation only: no reroll, new grant, consumed dialogue or claim mutation.
update public.adventure_encounter_plans p set snapshot=jsonb_set(p.snapshot,'{giftSnapshot,asset}',u.asset)
from gift_art260_updates u where p.gift_id=u.id and p.snapshot->'giftSnapshot'->>'stable_id'=u.id
 and p.snapshot->'giftSnapshot'->'asset'->>'key'=u.old_key;
update public.adventure_results r set metadata=jsonb_set(r.metadata,'{giftSnapshot,asset}',u.asset)
from gift_art260_updates u where r.metadata->'giftSnapshot'->>'stable_id'=u.id
 and r.metadata->'giftSnapshot'->'asset'->>'key'=u.old_key;
update public.adventure_results r set metadata=jsonb_set(r.metadata,'{itemSnapshot,asset}',u.asset)
from gift_art260_updates u where r.metadata->'itemSnapshot'->>'stable_id'=u.id
 and r.metadata->'itemSnapshot'->'asset'->>'key'=u.old_key;
commit;
